<?php
namespace App\Http\Controllers;
use App\Models\{User,AccountLifecycleProposal as Proposal,AccountLifecycleState as State};
use App\Support\{AccountLifecycle as L,LearningAccess};
use Illuminate\Http\Request;
use Illuminate\Support\Str;
class AccountLifecycleController extends Controller {
 private function allowed(Request $r):void {abort_unless(LearningAccess::manager($r->user())&&!L::blocked($r->user()),403);}
 private function view(string $name,array $data){return response()->view('account-operations.'.$name,$data)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 public function index(Request $r){$this->allowed($r);$d=$r->validate(['q'=>'nullable|string|max:100','user_id'=>'nullable|integer|min:1','case'=>'nullable|uuid','page'=>'nullable|integer|min:1']);$target=isset($d['user_id'])?User::findOrFail($d['user_id']):null;$people=User::when(filled($d['q']??null),fn($q)=>$q->where(fn($q)=>$q->where('name','like','%'.$d['q'].'%')->orWhere('email','like','%'.$d['q'].'%')))->orderBy('name')->paginate(30)->withQueryString();return $this->view('index',['people'=>$people,'target'=>$target,'source'=>$target?L::source($target,$d['case']??null):null,'case'=>$d['case']??null,'token'=>(string)Str::uuid(),'state'=>$target?State::find($target->id):null,'proposals'=>Proposal::when($target,fn($q)=>$q->where('target_id',$target->id))->orderByDesc('created_at')->limit(20)->get(),'q'=>$d['q']??'']);}
 public function prepare(Request $r,User $user){$this->allowed($r);$d=$r->validate(['request_token'=>'required|uuid','action'=>'required|in:Restrict,Archive,Restore','source_hash'=>'required|regex:/^[a-f0-9]{64}$/D','review_on'=>'required|date_format:Y-m-d','retention'=>'required|string|max:2000','handover'=>'nullable|string|max:2000','reason'=>'required|string|max:2000','case'=>'nullable|uuid','confirmed'=>'accepted']);$p=L::prepare($r->user(),(int)$r->session()->get('auth_version'),$user,$d['request_token'],$d['action'],$d['source_hash'],$d['review_on'],$d['retention'],$d['handover']??'',$d['reason'],$d['case']??null);return to_route('account-operations.show',$p)->with('status','Proposal saved. Another authorised operator must review it before any login change.');}
 public function show(Request $r,Proposal $proposal){$this->allowed($r);abort_unless(L::intact($proposal),409,'Proposal integrity needs recovery.');return $this->view('show',['p'=>$proposal,'target'=>User::findOrFail($proposal->target_id),'source_current'=>L::source(User::findOrFail($proposal->target_id),$proposal->details['input']['case'])['hash']===$proposal->source_hash]);}
 public function review(Request $r,Proposal $proposal){$this->allowed($r);$d=$r->validate(['version'=>'required|integer|min:1','accept'=>'required|boolean','override'=>'nullable|boolean','reference'=>'required|string|max:2000','confirmed'=>'accepted']);L::review($r->user(),(int)$r->session()->get('auth_version'),$proposal,(int)$d['version'],(bool)$d['accept'],$d['reference'],(bool)($d['override']??false));return back()->with('status','Independent account review recorded.');}
 public function apply(Request $r,Proposal $proposal){$this->allowed($r);$d=$r->validate(['version'=>'required|integer|min:1','confirmed'=>'accepted']);L::apply($r->user(),(int)$r->session()->get('auth_version'),$proposal,(int)$d['version']);return back()->with('status','Reviewed account operation applied. Evidence and assignments remain retained; restored accounts use the normal invitation/recovery process.');}
 public function retain(Request $r,User $user){$this->allowed($r);$d=$r->validate(['version'=>'required|integer|min:1','review_on'=>'required|date_format:Y-m-d','reference'=>'required|string|max:2000','reason'=>'required|string|max:2000','confirmed'=>'accepted']);L::retain($r->user(),(int)$r->session()->get('auth_version'),$user,(int)$d['version'],$d['review_on'],$d['reference'],$d['reason']);return back()->with('status','Retention review recorded. Login and retained records were not changed.');}
 public function ledger(Request $r){$this->allowed($r);return response(L::ledger($r->user()),200,['Content-Type'=>'application/octet-stream','Content-Disposition'=>'attachment; filename="GTA-Account-Restrictions.gta"','Cache-Control'=>'no-store, private','Referrer-Policy'=>'no-referrer']);}
 public function inspect(Request $r){$this->allowed($r);$d=$r->validate(['ledger'=>'required|file|max:2048','confirmed'=>'accepted']);$report=L::inspectLedger($r->user(),file_get_contents($d['ledger']->getRealPath()));return $this->view('ledger',['report'=>$report]);}
}
